#include <map>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::map<int, int> source{{1, 7}}, target;
    auto node = source.extract(1);
    assert(!node.empty() && node.key() == 1 && node.mapped() == 7);
    target.insert(std::move(node));
    assert(node.empty() && target.at(1) == 7);
}
